import React, { useState } from 'react';
import DatePicker from 'react-datepicker';
import 'react-datepicker/dist/react-datepicker.css';
import TimePicker from 'react-time-picker';

const Appointment = () => {
  const initialFormData = {
    APatientName: '',
    APatientDOB: null,
    ADate: null,
    ATime: '',
    ahId: '',
    ADId: '',
    AType: '',
    AMobile: '',
    AEmail: '',
    AReason: '',
  };

  const [formData, setFormData] = useState(initialFormData);

  const [formErrors, setFormErrors] = useState({});

  const validateForm = () => {
    const errors = {};

    // Validate APatientName
    if (!formData.APatientName.trim()) {
      errors.APatientName = 'Name is required';
    }

    // Validate APatientDOB
    if (!formData.APatientDOB) {
      errors.APatientDOB = 'Date of Birth is required';
    }

    // Validate ADate
    if (!formData.ADate) {
      errors.ADate = 'Appointment Date is required';
    }

    // Validate ATime
    if (!formData.ATime.trim()) {
      errors.ATime = 'Appointment Time is required';
    }

    // Validate ahId
    if (!formData.ahId) {
      errors.ahId = 'Select a Hospital';
    }

    // Validate ADId
    if (!formData.ADId) {
      errors.ADId = 'Select a Doctor';
    }

    // Validate AType
    if (!formData.AType.trim()) {
      errors.AType = 'Appointment Type is required';
    }

    // Validate AMobile
    if (!formData.AMobile.trim()) {
      errors.AMobile = 'Contact No. is required';
    } else if (!/^\d+$/.test(formData.AMobile)) {
      errors.AMobile = 'Invalid Contact No.';
    }

    // Validate AEmail
    if (!formData.AEmail.trim()) {
      errors.AEmail = 'Email is required';
    } else if (!/\S+@\S+\.\S+/.test(formData.AEmail)) {
      errors.AEmail = 'Invalid Email address';
    }

    // Validate AReason
    if (!formData.AReason.trim()) {
      errors.AReason = 'Appointment Reason is required';
    }

    setFormErrors(errors);

    return Object.keys(errors).length === 0; // Return true if there are no errors
  };

  const handleSubmitA = (e) => {
    e.preventDefault();

    // Validate the form before submitting
    if (validateForm()) {
      // The form is valid, proceed with your submit logic
      console.log('Form submitted:', formData);
      // Add your submit logic here
    } else {
      // The form is invalid, handle errors or show a message to the user
      console.log('Form has errors. Please check.');
    }
  };

  // ... your other functions (handleInputChangeA, handleDOBChange, handleApptDateChange) remain unchanged
  return (
    <div className="container-fluid bg-primary my-3 py-5">
          <div className="container py-5">
            <div className="row gx-5">
              <div className="col-lg-6 mb-5 mb-lg-0">
                <div className="mb-4">
                  <h5 className="d-inline-block text-white text-uppercase border-bottom border-5">
                    Appointment
                  </h5>
                  <h1 className="display-4">Make An Appointment</h1>
                </div>
                <p className="text-white mb-5">
                  Make an appointment with the hospital of your choice in your
                  comfortable time
                </p>
              </div>

              <div className="col-lg-6">
                <div className="bg-white text-center rounded p-5">
                  <h1 className="mb-4">Book An Appointment</h1>
                  <form onSubmit={handleSubmitA}>
                    <div className="row g-3">
                      <div className="col-12">
                        <input
                          type="text"
                          className="form-control bg-light border-0"
                          placeholder="Your Name"
                          style={{ height: 55 }}
                          name="APatientName"
                          value={formData.APatientName}
                          onChange={handleInputChangeA}
                        />
                      </div>
                      <div className="col-12">
                        <DatePicker
                          selected={formData.APatientDOB}
                          className="form-control bg-light border-0"
                          onChange={handleDOBChange}
                          placeholderText="Date Of Birth (mm/dd/yyyy)"
                          dateFormat="MM/dd/yyyy"
                          peekNextMonth
                          showMonthDropdown
                          showYearDropdown
                          dropdownMode="select"
                          maxDate={new Date()}
                        />
                      </div>
                      <div className="col-12">
                        <DatePicker
                          selected={formData.ADate}
                          onChange={handleApptDateChange}
                          className="form-control bg-light border-0"
                          placeholderText="Select Appointment Date (mm/dd/yyyy)"
                          dateFormat="MM/dd/yyyy"
                          peekNextMonth
                          showMonthDropdown
                          showYearDropdown
                          dropdownMode="select"
                          minDate={new Date()}
                        />
                      </div>
                      <div className="col-12">
                        <TimePicker
                          className="form-control bg-light border-0"
                          onChange={(time) =>
                            setFormData((prevFormData) => ({
                              ...prevFormData,
                              ATime: time,
                            }))
                          }
                          value={formData.ATime}
                          format="HH:mm"
                          clearIcon={null} // To hide the clear icon
                          style={{ fontSize: "16px", width: "100%" }} // Adjust the font size and width as needed
                        />
                      </div>
                      <div className="col-12">
                        <select
                          className="form-select bg-light border-0"
                          style={{ height: 55 }}
                          name="ahId"
                          value={formData.ahId}
                          onChange={handleInputChangeA}
                        >
                          <option selected>Select Hospital</option>
                          {hospitals.map((hospital) => (
                            <option key={hospital.hId} value={hospital.hId}>
                              {hospital.hName}
                            </option>
                          ))}
                        </select>
                      </div>
                      <div className="col-12">
                        <select
                          className="form-select bg-light border-0"
                          style={{ height: 55 }}
                          name="ADId"
                          value={formData.ADId}
                          onChange={handleInputChangeA}
                        >
                          <option selected>Select Doctor</option>
                          {doctors.map((doctor) => (
                            <option key={doctor.dId} value={doctor.dId}>
                              {doctor.dName}
                            </option>
                          ))}
                        </select>
                      </div>
                      <div className="col-12">
                        <input
                          type="text"
                          className="form-control bg-light border-0"
                          placeholder="Select Appointment Type"
                          style={{ height: 55 }}
                          name="AType"
                          value={formData.AType}
                          onChange={handleInputChangeA}
                        />
                      </div>
                      <div className="col-12">
                        <input
                          type="tel"
                          className="form-control bg-light border-0"
                          placeholder="Contact No."
                          style={{ height: 55 }}
                          name="AMobile"
                          value={formData.AMobile}
                          onChange={handleInputChangeA}
                        />
                      </div>
                      <div className="col-12">
                        <input
                          type="email"
                          className="form-control bg-light border-0"
                          placeholder="Your Email"
                          style={{ height: 55 }}
                          name="AEmail"
                          value={formData.AEmail}
                          onChange={handleInputChangeA}
                        />
                      </div>
                      <div className="col-12">
                        <textarea
                          className="form-control bg-light border-0"
                          placeholder="Appointment Reason"
                          style={{ height: 100 }}
                          name="AReason"
                          value={formData.AReason}
                          onChange={handleInputChangeA}
                        ></textarea>
                      </div>
                      <div className="col-12">
                        <button
                          className="btn btn-primary w-100 py-3"
                          type="submit"
                        >
                          Make An Appointment
                        </button>
                      </div>
                    </div>
                  </form>
                </div>
              </div>
            </div>
          </div>
        </div>
  );
};

export default Appointment;
